class Resource extends Vector {
 heading='An instrument for wondering.';note='A calibrated study of rings, planes and light.';
 build(){const count=this.number('detail',7,3,12),tilt=(this.tilt??this.number('strength',35,10,70))*Math.PI/180,id=this.artId;let paths='';for(let plane=0;plane<count;plane++){let d='';const phase=plane*Math.PI/count;for(let j=0;j<=180;j++){const a=j/180*Math.PI*2,r=143;let x=Math.cos(a)*r,y=Math.sin(a)*r*Math.cos(phase),z=Math.sin(a)*r*Math.sin(phase);const yy=y*Math.cos(tilt)-z*Math.sin(tilt),zz=y*Math.sin(tilt)+z*Math.cos(tilt),xx=x*Math.cos(.4)-zz*Math.sin(.4);d+=(j?'L':'M')+(360+xx).toFixed(2)+' '+(210+yy).toFixed(2);}paths+=`<path d="${d}" fill="none" stroke="${plane%3===0?this.color:'#b29b73'}" stroke-width="${plane%3===0?1.8:.7}" opacity="${.4+plane/count*.4}"/>`;}
 const ticks=Array.from({length:120},(_,i)=>{const a=i*Math.PI/60,r=i%5?171:166;return`<path d="M${360+Math.cos(a)*r} ${210+Math.sin(a)*r}L${360+Math.cos(a)*178} ${210+Math.sin(a)*178}" stroke="#c3af85" stroke-width="${i%5?.5:1}" opacity="${i%5?.35:.7}"/>`;}).join('');return this.svg(`<defs><radialGradient id="${id}-sun"><stop stop-color="#fff3c3"/><stop offset=".5" stop-color="#d5b47d"/><stop offset="1" stop-color="#675538"/></radialGradient></defs><circle cx="360" cy="210" r="183" fill="#171d1d" stroke="#7d715866"/>${ticks}${paths}<circle cx="360" cy="210" r="26" fill="url(#${id}-sun)"/><path d="M180 210h40m280 0h40M360 30v40m0 280v40" stroke="#cbb78b44"/><text x="360" y="19" text-anchor="middle" fill="#bdad89" font-family="monospace" font-size="8" letter-spacing="3">N / 00°</text><text x="360" y="410" text-anchor="middle" fill="#bdad89" font-family="monospace" font-size="8" letter-spacing="3">ORBITAL INSTRUMENT / ${count} PLANES</text>`);}
 hover(point){if(this.reduced)return;const tilt=clamp((point.y-40)/340*60+10,10,70);if(Math.abs(tilt-(this.tilt||0))>2){this.tilt=tilt;this.draw();}}
 configured(name){if(name==='strength')this.tilt=null;super.configured(name);}
}
